SOURCE='SOURCE'

def remove_switches(topo, compute_nodes, root_caps):
    # topo DiGraph with capacities, no SOURCE
    flow_graph=nx.DiGraph(topo)
    D=sum(root_caps.values())
    flow_graph.add_node(SOURCE)
    for b in compute_nodes:
        flow_graph.add_edge(SOURCE,b,capacity=root_caps[b])
    edge_map={}
    comp=set(compute_nodes)
    for w in sorted(v for v in list(flow_graph.nodes()) if v not in comp and v!=SOURCE):
        for u in sorted(flow_graph.predecessors(w)):
            if not flow_graph.has_edge(u,w): continue
            while flow_graph.has_edge(u,w) and flow_graph[u][w]['capacity']>0:
                # legacy loops successors and subtracts whole edge per t? It asserts after all t edge zero
                for t in sorted(flow_graph.successors(w)):
                    if not flow_graph.has_edge(w,t): continue
                    M=min(flow_graph[u][w]['capacity'], flow_graph[w][t]['capacity'])
                    flow_graph.add_edge(u,SOURCE)
                    cpct_ut=flow_graph[u][t]['capacity'] if flow_graph.has_edge(u,t) else 0
                    if cpct_ut==0:
                        flow_graph.add_edge(u,t)
                    else:
                        del flow_graph[u][t]['capacity']
                    for v in compute_nodes:
                        if u==v or t==v: continue
                        cpct_vw=flow_graph[v][w]['capacity'] if flow_graph.has_edge(v,w) else 0
                        if cpct_vw==0: flow_graph.add_edge(v,w)
                        else: del flow_graph[v][w]['capacity']
                        fval=nx.maximum_flow_value(flow_graph,u,w) - D
                        M=min(fval,M)
                        if cpct_vw==0: flow_graph.remove_edge(v,w)
                        else: flow_graph[v][w]['capacity']=cpct_vw
                        if M==0: break
                    flow_graph.remove_edge(u,SOURCE)
                    if M>0:
                        flow_graph.add_edge(w,SOURCE)
                        for v in compute_nodes:
                            if v!=u:
                                cpct_vt=flow_graph[v][t]['capacity'] if flow_graph.has_edge(v,t) else 0
                                if cpct_vt==0: flow_graph.add_edge(v,t)
                                else: del flow_graph[v][t]['capacity']
                                fval=nx.maximum_flow_value(flow_graph,w,t)-D
                                if cpct_vt==0: flow_graph.remove_edge(v,t)
                                else: flow_graph[v][t]['capacity']=cpct_vt
                            else:
                                fval=nx.maximum_flow_value(flow_graph,w,t)-D
                            M=min(fval,M)
                            if M==0: break
                        flow_graph.remove_edge(w,SOURCE)
                    if cpct_ut==0: flow_graph.remove_edge(u,t)
                    else: flow_graph[u][t]['capacity']=cpct_ut
                    if M==0: continue
                    if (u,t) not in edge_map: edge_map[u,t]={}
                    if w not in edge_map[u,t]: edge_map[u,t][w]=0
                    edge_map[u,t][w]+=M
                    flow_graph[u][w]['capacity']-=M
                    flow_graph[w][t]['capacity']-=M
                    if flow_graph.has_edge(u,t): flow_graph[u][t]['capacity']+=M
                    elif u!=t: flow_graph.add_edge(u,t,capacity=M)
                    if flow_graph[w][t]['capacity']==0: flow_graph.remove_edge(w,t)
                    if flow_graph[u][w]['capacity']==0: break
                assert not flow_graph.has_edge(u,w) or flow_graph[u][w]['capacity']==0
                if flow_graph.has_edge(u,w): flow_graph.remove_edge(u,w)
        # assert all incident done
        for n in list(flow_graph.nodes()):
            if n not in comp and n!=SOURCE:
                if flow_graph.has_edge(n, w) or flow_graph.has_edge(w,n): print('leftover',w,n)
    # remove switch nodes and SOURCE
    for n in list(flow_graph.nodes()):
        if n not in comp and n!=SOURCE:
            flow_graph.remove_node(n)
    flow_graph.remove_node(SOURCE)
    return flow_graph,edge_map

def gen(topo, roots):
    # adapted BranchingGenerator
    class Gen:
      def __init__(self, topo, roots):
        self.flow_graph=nx.DiGraph(topo)
        self.roots={u:c for u,c in roots.items() if c>0}
        self.s_nodes={(u,0):('SOURCE',u,0) for u in self.roots}
        self.flow_graph.add_nodes_from(self.s_nodes.values())
        for (u,_),s in self.s_nodes.items(): self.flow_graph.add_edge(s,u)
        self.num=sum(self.roots.values())
        self.Tcount={u:1 for u in self.roots}
        self.Ts={(u,0):[] for u in self.roots}
        self.Vs={(u,0):{u} for u in self.roots}
        self.Cs={(u,0):c for u,c in self.roots.items()}
      def new_tree(self,root,edges,nodes,num):
        idx=self.Tcount[root]; self.Tcount[root]+=1
        s=('SOURCE',root,idx); self.s_nodes[root,idx]=s
        self.flow_graph.add_node(s)
        for v in nodes: self.flow_graph.add_edge(s,v)
        self.Ts[root,idx]=list(edges); self.Vs[root,idx]=set(nodes); self.Cs[root,idx]=num
      def test_edge(self,w,j,x,y):
        cs=0
        for (u,i),s in list(self.s_nodes.items()):
          if (u,i)!=(w,j):
            self.flow_graph.add_edge(x,s,capacity=self.Cs[u,i]); cs+=self.Cs[u,i]
        assert self.Cs[w,j]>0 and self.flow_graph[x][y]['capacity']>0
        f=nx.maximum_flow_value(self.flow_graph,x,y)
        chunks=min(self.Cs[w,j],self.flow_graph[x][y]['capacity'],f-cs)
        for (u,i),s in self.s_nodes.items():
          if (u,i)!=(w,j): self.flow_graph.remove_edge(x,s)
        return chunks
      def generate(self):
        trees=sorted(self.s_nodes.keys())
        loops=0
        while trees:
          w,j=trees.pop(0)
          s_node=self.s_nodes[w,j]
          q=list(self.Vs[w,j])
          while q:
            x=q.pop(0); loops+=1
            if loops>100000: raise RuntimeError('loop')
            for y in sorted(self.flow_graph.successors(x)):
              if y in self.Vs[w,j] or y in self.s_nodes.values(): continue
              if not self.flow_graph.has_edge(x,y) or self.flow_graph[x][y].get('capacity',0)<=0: continue
              chunks=self.test_edge(w,j,x,y)
              if chunks<=0: continue
              q.append(y)
              if chunks<self.Cs[w,j]:
                trees.append(self.new_tree(w,self.Ts[w,j],self.Vs[w,j],self.Cs[w,j]-chunks))
                self.Cs[w,j]=chunks
              self.Ts[w,j].append((x,y)); self.Vs[w,j].add(y)
              assert not self.flow_graph.has_edge(s_node,y)
              self.flow_graph.add_edge(s_node,y)
              self.flow_graph[x][y]['capacity']-=chunks
              if self.flow_graph[x][y]['capacity']==0: self.flow_graph.remove_edge(x,y)
          assert len(self.Vs[w,j])==len(self.roots), (len(self.Vs[w,j]),len(self.roots),topo.nodes())
          assert len(self.Ts[w,j])==len(self.roots)-1
          self.flow_graph.remove_node(self.s_nodes[w,j]); del self.s_nodes[w,j]
          self.num-=self.Cs[w,j]
        assert self.num==0
        return self.Ts,self.Cs
    return Gen(topo,roots).generate()

def cuts_ok(topo, roots):
    comp=list(roots)
    D=sum(roots.values())
    # graph with SOURCE capacities
    for v in comp:
      for r in range(1,1<<len(comp)):
        # test each S subset requiring cap out >= sum roots in S
        pass
    # use maxflow source->v>=D
    G=nx.DiGraph(topo); G.add_node(SOURCE)
    for u,c in roots.items(): G.add_edge(SOURCE,u,capacity=c)
    for v in comp:
      if nx.maximum_flow_value(G,SOURCE,v)<D: return False,('sink',v)
    return True,None

def direct_cut_ok(topo, roots):
    comp=list(roots); D=sum(roots.values())
    # enumerate subsets participants nonempty proper
    n=len(comp)
    for mask in range(1,(1<<n)-1):
      S={comp[i] for i in range(n) if mask>>i&1}
      cap=sum(d.get('capacity',0) for u,v,d in topo.edges(data=True) if (u in S)!=(v in S))
      R=sum(roots[u] for u in S)
      if cap<R: return False,(S,cap,R)
    return True,None

